const removeLinesWithSubStrings = ['await', '...'];
const cleanFileString = (str) => {
    let lines = str.split('\n');
    const rx = /(?<=jacdac\.)([^\s]*)(?=,)/gm;
    //console.log('str: ', str)
    const matched = str.match(rx);
    //console.log('matched: ', matched)
    const finalLines = [];
    for (let i = 0; i < lines.length; i++) {
        let line = lines[i];
        if (line.includes("jacdac.")) {
            line = line.replace("jacdac.", "typeof ");
        }
        const found = removeLinesWithSubStrings.some((item) => { return line.includes(item); });
        if (!found) {
            // 
            finalLines.push(line);
        }
    }
    return finalLines.join('\n');
};
