function createMaxOutlet(packet, packetInfo) {
    const { kind, name } = packet;
    const messageTag = camelize(name);
    const { buffers, names, types, pyTypes, csTypes } = packetInfo;
    let namesString = '';
    for (let n = 0; n < names.length; n++) {
        const name = names[n];
        if (n < names.length - 1) {
            namesString = namesString.concat(`${name}.toString(),`);
        }
        else {
            namesString = namesString.concat(`${name}.toString()`);
        }
    }
    let stringToReturn = `maxApi.outlet([service.maxID.toString(), "${messageTag}", ${namesString}])`;
    return stringToReturn;
}
function generateServiceMapFile(services) {
    let serviceMapHeader = `const jd = require('jacdac-ts');\n`;
    // services = services.filter(service => {service.extends.includes("_sensor")})
    services.forEach(service => {
        if (service.extends.includes("_sensor")) {
            const serviceName = service.camelName.charAt(0).toUpperCase() + service.camelName.slice(1);
            serviceMapHeader += `const {${serviceName}} = require('./${serviceName}');\n`;
        }
    });
    let serviceMapFunctionString = serviceMapHeader + `\n\nexports.serviceMap = function(service){\n`;
    serviceMapFunctionString +=
        `
        if (service.serviceClass === null || service.serviceClass === undefined){
        return 'SERVICE NOT DEFINED';
        }`;
    services.forEach(service => {
        if (service.extends.includes("_sensor")) {
            const serviceName = service.camelName.charAt(0).toUpperCase() + service.camelName.slice(1);
            serviceMapFunctionString +=
                `
            else if (service.serviceClass === ${service.classIdentifier}){
                ${serviceName}(service)
            }\n`;
        }
    });
    serviceMapFunctionString += '\n}\n';
    serviceMapFunctionString += 'export {}';
    const prefix = './src/max_service_object_generator/autogen_src/';
    const filename = 'serviceMap';
    const filecontent = serviceMapFunctionString;
    fs.writeFile(prefix + `${filename}.ts`, filecontent, function (err) {
        if (err) {
            console.log('ERROR WRITING FILE: ', err);
        }
        throw err;
        console.log('File is created successfully.');
    });
}
